/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --card-border: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --primary: #38bdf8;
  --primary-hover: #0ea5e9;
  --primary-active: #0284c7;
  --success-text: #4ade80;
  --error-text: #f87171;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--bg-color);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-main);
  padding: 1.5rem 1rem;
}

.game-card {
  background-color: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 1rem;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 480px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  text-align: center;
}

.game-header {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.game-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
}

.game-subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.score-box {
  background-color: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--card-border);
  border-radius: 0.5rem;
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.score-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.target-display {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-items: center;
}

.target-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.rgb-display {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background-color: rgba(15, 23, 42, 0.9);
  color: var(--text-main);
  padding: 0.75rem 1.25rem;
  border-radius: 0.5rem;
  border: 1px solid var(--card-border);
  user-select: all;
  display: inline-block;
}

.swatch-group {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.swatch-btn {
  aspect-ratio: 1 / 1;
  width: 100%;
  border-radius: 0.75rem;
  border: 3px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3);
  outline: none;
}

.swatch-btn:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 8px 12px -2px rgba(0, 0, 0, 0.4);
}

.swatch-btn:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

.swatch-btn:focus-visible {
  border-color: #ffffff;
  box-shadow: 0 0 0 4px var(--primary);
}

.swatch-btn:disabled {
  cursor: default;
  opacity: 0.7;
}

.status-message {
  min-height: 1.5rem;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-muted);
  transition: color 0.2s ease;
}

.status-message.correct {
  color: var(--success-text);
}

.status-message.incorrect {
  color: var(--error-text);
}

.controls {
  display: flex;
  justify-content: center;
}

.action-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  background-color: var(--primary);
  color: #0f172a;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.15s ease;
  outline: none;
}

.action-btn:hover {
  background-color: var(--primary-hover);
}

.action-btn:active {
  background-color: var(--primary-active);
  transform: scale(0.98);
}

.action-btn:focus-visible {
  box-shadow: 0 0 0 3px #ffffff, 0 0 0 5px var(--primary);
}

@media (max-width: 400px) {
  .game-card {
    padding: 1.25rem;
    gap: 1.25rem;
  }

  .rgb-display {
    font-size: 1.25rem;
    padding: 0.5rem 0.75rem;
  }

  .swatch-group {
    gap: 0.5rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let currentStreak = 0;
  let bestStreak = 0;
  let targetColor = '';
  let correctIndex = 0;
  let roundLocked = false;

  const currentScoreEl = document.getElementById('current-score');
  const bestStreakEl = document.getElementById('best-streak');
  const rgbCodeEl = document.getElementById('rgb-code');
  const statusMessageEl = document.getElementById('status-message');
  const restartBtn = document.getElementById('restart-btn');
  const swatchButtons = [
    document.getElementById('swatch-0'),
    document.getElementById('swatch-1'),
    document.getElementById('swatch-2')
  ];

  function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateRandomColor() {
    const r = getRandomInt(0, 255);
    const g = getRandomInt(0, 255);
    const b = getRandomInt(0, 255);
    return `rgb(${r}, ${g}, ${b})`;
  }

  function generateDistinctDistractors(baseColor) {
    const colors = [baseColor];
    while (colors.length < 3) {
      const candidate = generateRandomColor();
      if (!colors.includes(candidate)) {
        colors.push(candidate);
      }
    }
    return colors.slice(1);
  }

  function updateStatus(text, type = '') {
    statusMessageEl.textContent = text;
    statusMessageEl.className = 'status-message';
    if (type) {
      statusMessageEl.classList.add(type);
    }
  }

  function startRound() {
    roundLocked = false;
    targetColor = generateRandomColor();
    correctIndex = getRandomInt(0, 2);
    const distractors = generateDistinctDistractors(targetColor);

    rgbCodeEl.textContent = targetColor;

    let distractorIndex = 0;
    swatchButtons.forEach((btn, idx) => {
      btn.disabled = false;
      if (idx === correctIndex) {
        btn.style.backgroundColor = targetColor;
      } else {
        btn.style.backgroundColor = distractors[distractorIndex];
        distractorIndex++;
      }
    });
  }

  function handleGuess(selectedIndex) {
    if (roundLocked) return;
    roundLocked = true;

    if (selectedIndex === correctIndex) {
      currentStreak += 1;
      if (currentStreak > bestStreak) {
        bestStreak = currentStreak;
        bestStreakEl.textContent = bestStreak;
      }
      currentScoreEl.textContent = currentStreak;
      updateStatus('Correct! Advancing to next round...', 'correct');

      setTimeout(() => {
        updateStatus('Choose a color swatch to continue.');
        startRound();
      }, 800);
    } else {
      currentStreak = 0;
      currentScoreEl.textContent = currentStreak;
      updateStatus(`Wrong! That round ended. Target was ${targetColor}. Click New Game or select to retry.`, 'incorrect');

      swatchButtons.forEach((btn, idx) => {
        if (idx !== correctIndex) {
          btn.disabled = true;
        }
      });
    }
  }

  function resetGame() {
    currentStreak = 0;
    currentScoreEl.textContent = currentStreak;
    updateStatus('New game started! Guess the swatch.');
    startRound();
  }

  swatchButtons.forEach((button, index) => {
    button.addEventListener('click', () => {
      handleGuess(index);
    });
  });

  restartBtn.addEventListener('addEventListener' in restartBtn ? 'click' : 'click', resetGame);

  // Initial round setup
  startRound();
});
